/**
 * M6 worker bootstrap: boots the Node-RED flow ONCE (nodes stay alive and
 * wired for the worker's whole lifetime, per the architecture rule), installs
 * a single `Capture` instance against it, builds the real `executeNode`
 * Activity, and registers both with a real `@temporalio/worker` Worker.
 *
 * Exports a plain `createWorker(options)` factory - no CLI wiring here; M7
 * owns turning this into a `bin/node-red-temporal` subcommand.
 *
 * --- Known caveat: at-least-once Activity execution (A2 #1) ---
 * Temporal Activities are at-least-once. If this worker process is killed
 * while `executeNode` is mid-flight against a side-effecting node (e.g. an
 * `http request` node that already sent the HTTP call but the process dies
 * before the Activity resolves), Temporal WILL re-schedule and re-run that
 * same Activity invocation on worker restart, re-firing the side effect.
 * This milestone does not attempt to solve or hide that; it is a known,
 * documented limitation of the MVP recovery model (full demonstration is
 * M8's job, killing the worker BETWEEN Activities, not mid-Activity).
 */

"use strict";

const { Worker } = require("@temporalio/worker");
const { bootstrap } = require("./bootstrap");
const { Capture } = require("./capture");
const { createExecuteNode } = require("./activities");
// Same `@node-red/util` module bootstrap.js already uses for `redUtil.init`/
// `redUtil.events` - it exposes the `hooks` API Capture.install() needs, so
// no test-only helper (`nr-test-utils`) is pulled into production code.
const redUtil = require("../../../@node-red/util");

const WORKFLOWS_PATH = require.resolve("./workflows.js");

/**
 * @param {string} flowFilePath - path to a Node-RED flows.json file
 * @param {object} [options]
 * @param {object} [options.bootstrapOptions] - forwarded to `bootstrap()`
 * @param {object} [options.captureOptions] - forwarded to `new Capture()`
 * @param {object} [options.workerOptions] - merged into `Worker.create()` options
 * @returns {Promise<{worker: Worker, handle: object, capture: Capture, stop: function(): Promise<void>}>}
 */
async function createWorker(flowFilePath, options) {
    options = options || {};
    const handle = await bootstrap(flowFilePath, options.bootstrapOptions);
    const capture = new Capture(options.captureOptions);
    capture.install(redUtil);

    const executeNode = createExecuteNode({
        getNode: handle.getNode,
        flowVersion: handle.flowVersion,
        capture
    });

    const worker = await Worker.create(Object.assign(
        {
            workflowsPath: WORKFLOWS_PATH,
            activities: { executeNode },
            taskQueue: "node-red-temporal"
        },
        options.workerOptions || {}
    ));

    return {
        worker,
        handle,
        capture,
        flowVersion: handle.flowVersion,
        async stop() {
            worker.shutdown();
            capture.uninstall();
            await handle.stop();
        }
    };
}

module.exports = { createWorker, WORKFLOWS_PATH };
